@app.cell
def _(alt, pd):
    # -------------------------------------------------------------------------
    # HELPERS
    # -------------------------------------------------------------------------
    def read_csv_checked(path, required_columns, allow_empty=False):
        if not path.exists():
            raise FileNotFoundError(f"CSV not found: {path}")
        df = pd.read_csv(path, low_memory=False)
        missing = [c for c in required_columns if c not in df.columns]
        if missing:
            raise ValueError(
                f"{path.name} is missing required columns: {missing}\n"
                f"Available columns: {df.columns.tolist()}"
            )
        if df.empty and not allow_empty:
            raise ValueError(f"{path.name} contains no rows")
        return df

    def numeric_inplace(df, columns):
        out = df.copy()
        for col in columns:
            if col in out.columns:
                out[col] = pd.to_numeric(out[col], errors="coerce")
        return out

    def first_existing(columns, candidates):
        available = set(columns)
        return next((c for c in candidates if c in available), None)

    def available_stat_columns(df):
        preferred = [
            "p_motion_specific_two_sided",
            "p_ttest_two_sided",
            "q_motion_specific_two_sided",
            "q_ttest_two_sided",
            "p_motion_baseline_two_sided_screen",
            "q_motion_baseline_two_sided_screen",
            "p_direction_tuning_permutation_screen",
            "q_direction_tuning_permutation_screen",
        ]
        discovered = [
            c
            for c in df.columns
            if c.startswith(("p_", "q_", "is_"))
            or "p_value" in c.lower()
            or "q_value" in c.lower()
        ]
        ordered = []
        for col in preferred + discovered:
            if col in df.columns and col not in ordered:
                ordered.append(col)
        return ordered

    def clean_label(value):
        return str(value).replace("_", " ")

    def close_polar_frame(df, value_columns):
        if df.empty:
            return df.copy()
        pieces = []
        group_cols = [c for c in ["source_name", "unit_uid", "screen_role", "speed"] if c in df]
        if not group_cols:
            groups = [(None, df)]
        else:
            groups = df.groupby(group_cols, dropna=False, sort=False)
        for _, group in groups:
            group = group.sort_values(["direction_order", "direction"], kind="stable")
            if group.empty:
                continue
            first = group.iloc[[0]].copy()
            first["direction_plot"] = pd.to_numeric(first["direction"], errors="coerce") + 360
            current = group.copy()
            current["direction_plot"] = pd.to_numeric(current["direction"], errors="coerce")
            pieces.extend([current, first])
        if not pieces:
            return df.iloc[0:0].copy()
        result = pd.concat(pieces, ignore_index=True)
        keep_cols = list(dict.fromkeys(list(df.columns) + ["direction_plot"] + value_columns))
        return result[[c for c in keep_cols if c in result.columns]]

    def stat_table_long(df, id_columns, stat_columns):
        if df.empty or not stat_columns:
            return pd.DataFrame(columns=id_columns + ["statistic", "value"])
        existing_ids = [c for c in id_columns if c in df.columns]
        existing_stats = [c for c in stat_columns if c in df.columns]
        base = df[existing_ids + existing_stats].drop_duplicates().copy()
        return base.melt(
            id_vars=existing_ids,
            value_vars=existing_stats,
            var_name="statistic",
            value_name="value",
        )

    def empty_chart(message, width=520, height=240):
        placeholder = pd.DataFrame({"message": [message], "x": [0.5], "y": [0.5]})
        return (
            alt.Chart(placeholder)
            .mark_text(fontSize=15)
            .encode(
                x=alt.X("x:Q", axis=None, scale=alt.Scale(domain=[0, 1])),
                y=alt.Y("y:Q", axis=None, scale=alt.Scale(domain=[0, 1])),
                text="message:N",
            )
            .properties(width=width, height=height)
        )

    return (
        available_stat_columns,
        first_existing,
        numeric_inplace,
        read_csv_checked,
        stat_table_long,
    )


@app.cell
def _(
    DIRECTION_CSV,
    PATTERN_CSV,
    POPULATION_CSV,
    numeric_inplace,
    read_csv_checked,
):
    population_raw = read_csv_checked(
        POPULATION_CSV,
        [
            "source_name",
            "unit_id",
            "unit_uid",
            "pattern",
            "x_plot_um",
            "y_plot_um",
            "fraction_change",
        ],
    )
    pattern_raw = read_csv_checked(
        PATTERN_CSV,
        ["source_name", "unit_id", "unit_uid", "pattern"],
    )
    direction_raw = read_csv_checked(
        DIRECTION_CSV,
        [
            "source_name",
            "unit_id",
            "unit_uid",
            "screen_role",
            "speed",
            "direction",
            "trial_id",
            "baseline_fr_trial",
            "moving_fr_trial",
            "response_trial",
        ],
        allow_empty=True,
    )

    population_df = numeric_inplace(
        population_raw,
        [
            "x_um",
            "y_um",
            "x_plot_um",
            "y_plot_um",
            "fraction_change",
            "baseline_fr_mean",
            "moving_fr_mean",
            "pattern_order",
            "best_channel",
            "shank_id",
        ],
    )
    pattern_df = numeric_inplace(
        pattern_raw,
        [
            "pattern_order",
            "baseline_fr_mean",
            "baseline_fr_sem",
            "moving_fr_mean",
            "moving_fr_sem",
            "moving_minus_baseline_mean",
            "moving_minus_baseline_sem",
            "fraction_change",
            "n_trials",
        ],
    )
    direction_df = numeric_inplace(
        direction_raw,
        [
            "direction",
            "direction_order",
            "screen_order",
            "baseline_fr_trial",
            "moving_fr_trial",
            "response_trial",
            "fraction_change_trial",
        ],
    )

    for _frame in [population_df, pattern_df, direction_df]:
        if "unit_uid" in _frame.columns:
            _frame["unit_uid"] = _frame["unit_uid"].astype(str)
        if "source_name" in _frame.columns:
            _frame["source_name"] = _frame["source_name"].astype(str)
    return direction_df, pattern_df, population_df


@app.cell
def _(
    DEFAULT_ALPHA,
    DEFAULT_COLOR_DOMAIN,
    DEFAULT_POINT_SIZE,
    available_stat_columns,
    mo,
    population_df,
):
    source_options = sorted(population_df["source_name"].dropna().astype(str).unique())
    source_filter = mo.ui.multiselect(
        options=source_options,
        value=source_options,
        label="Sources",
    )

    candidate_significance_columns = available_stat_columns(population_df)
    numeric_sig_options = [
        c
        for c in candidate_significance_columns
        if c.startswith(("p_", "q_")) or "p_value" in c.lower() or "q_value" in c.lower()
    ]
    significance_options = ["Show all"] + numeric_sig_options
    # Start unfiltered so the app always shows the available population points.
    # The user can then choose any p/q column explicitly.
    default_sig = "p_motion_specific_two_sided"
    significance_filter = mo.ui.dropdown(
        options=significance_options,
        value=default_sig,
        label="Population filter",
    )
    alpha_filter = mo.ui.number(
        start=0.0,
        stop=1.0,
        step=0.001,
        value=DEFAULT_ALPHA,
        label="p/q threshold",
    )
    point_size = mo.ui.slider(
        start=15,
        stop=180,
        step=5,
        value=DEFAULT_POINT_SIZE,
        label="Point size",
    )
    color_domain = mo.ui.slider(
        start=0.25,
        stop=10.0,
        step=0.25,
        value=DEFAULT_COLOR_DOMAIN,
        label="Fraction-change color limit",
    )
    show_missing_coordinates = mo.ui.switch(
        value=False,
        label="Include rows missing coordinates",
    )

    controls = mo.hstack(
        [
            source_filter,
            significance_filter,
            alpha_filter,
            point_size,
            color_domain,
            show_missing_coordinates,
        ],
        widths=[2, 2, 1, 1, 1, 1],
        gap=1,
    )
    controls
    return (
        alpha_filter,
        color_domain,
        point_size,
        show_missing_coordinates,
        significance_filter,
        source_filter,
    )


