@app.cell
def _(
    PATTERN_LABELS,
    PATTERN_ORDER,
    alpha_filter,
    alt,
    color_domain,
    np,
    point_size,
    population_df,
    show_missing_coordinates,
    significance_filter,
    source_filter,
):
    selected_sources = list(source_filter.value or [])
    population_visible = population_df[
        population_df["source_name"].isin(selected_sources)
    ].copy()

    chosen_sig = significance_filter.value
    if chosen_sig != "Show all" and chosen_sig in population_visible.columns:
        sig_values = population_visible[chosen_sig]
        if sig_values.dtype == bool:
            population_visible = population_visible[sig_values.fillna(False)].copy()
        else:
            sig_numeric = np.asarray(
                population_visible[chosen_sig].pipe(lambda s: __import__("pandas").to_numeric(s, errors="coerce"))
            )
            population_visible = population_visible[
                np.isfinite(sig_numeric) & (sig_numeric < float(alpha_filter.value))
            ].copy()

    if not show_missing_coordinates.value:
        population_visible = population_visible.dropna(
            subset=["x_plot_um", "y_plot_um"]
        )

    population_visible["pattern_label"] = population_visible["pattern"].map(
        PATTERN_LABELS
    ).fillna(population_visible["pattern"].astype(str))
    population_visible["pattern_label"] = __import__("pandas").Categorical(
        population_visible["pattern_label"],
        categories=[PATTERN_LABELS.get(p, p) for p in PATTERN_ORDER],
        ordered=True,
    )

    tooltip_columns = [
        c
        for c in [
            "source_name",
            "unit_id",
            "unit_uid",
            "pattern",
            "shank_id",
            "best_channel",
            "x_um",
            "y_um",
            "baseline_fr_mean",
            "moving_fr_mean",
            "fraction_change",
            chosen_sig if chosen_sig != "Show all" else None,
        ]
        if c is not None and c in population_visible.columns
    ]

    point_pick = alt.selection_point(
        fields=["unit_uid", "pattern"],
        on="click",
        clear="dblclick",
        empty=False,
        name="population_point_pick",
    )

    population_chart_spec = (
        alt.Chart(population_visible)
        .mark_circle(
            size=int(point_size.value),
            stroke="black",
        )
        .encode(
            x=alt.X(
                "x_plot_um:Q",
                title="M–L position (µm)",
                scale=alt.Scale(zero=False),
            ),
            y=alt.Y(
                "y_plot_um:Q",
                title="Depth (µm)",
                scale=alt.Scale(zero=False),
            ),
            color=alt.Color(
                "fraction_change:Q",
                title="Fraction change",
                scale=alt.Scale(
                    scheme="redblue",
                    domain=[-float(color_domain.value), float(color_domain.value)],
                    clamp=True,
                    reverse=True,
                ),
            ),
            tooltip=tooltip_columns,
            opacity=alt.condition(point_pick, alt.value(1.0), alt.value(0.72)),
            strokeWidth=alt.condition(point_pick, alt.value(2.8), alt.value(0.25)),
            size=alt.condition(
                point_pick,
                alt.value(int(point_size.value) * 1.8),
                alt.value(int(point_size.value)),
            ),
        )
        .add_params(point_pick)
        .properties(width=235, height=310)
        .facet(
            facet=alt.Facet(
                "pattern_label:N",
                title=None,
                sort=[PATTERN_LABELS.get(p, p) for p in PATTERN_ORDER],
                header=alt.Header(labelFontSize=13, labelLimit=220),
            ),
            columns=4,
        )
        .resolve_scale(x="shared", y="shared", color="shared")
        .properties(title="12-pattern population maps")
    )
    return population_chart_spec, population_visible


@app.cell
def _(
    mo,
    population_df,
    population_visible,
    significance_filter,
    source_filter,
):
    total_rows = len(population_df)
    visible_rows = len(population_visible)
    selected_sources_count = len(source_filter.value or [])
    diagnostic = mo.md(
        f"**Population rows:** {visible_rows:,} visible / {total_rows:,} total  "
        f"| **Sources selected:** {selected_sources_count}  "
        f"| **Filter:** `{significance_filter.value}`"
    )
    if visible_rows == 0:
        diagnostic = mo.callout(
            mo.vstack([
                diagnostic,
                mo.md(
                    "No population points remain after filtering. Choose **Show all**, "
                    "increase the p/q threshold, or check whether the selected statistic "
                    "contains numeric values."
                ),
            ]),
            kind="warn",
        )
    diagnostic
    return


