@app.cell
def _(population_selector, population_visible):
    selected_rows = population_selector.value
    if selected_rows is None:
        selected_rows = population_visible.iloc[0:0].copy()
    elif not hasattr(selected_rows, "columns"):
        selected_rows = population_visible.iloc[0:0].copy()

    if selected_rows.empty:
        selected_unit_uid = None
        selected_pattern = None
        selected_point = None
    else:
        # A point selection should normally contain one row. Taking the last row
        # also behaves sensibly if a browser keeps more than one selected point.
        selected_point = selected_rows.iloc[-1]
        selected_unit_uid = str(selected_point["unit_uid"])
        selected_pattern = str(selected_point["pattern"])
    return selected_pattern, selected_point, selected_unit_uid


@app.cell
def _(mo, selected_pattern, selected_point, selected_unit_uid):
    if selected_unit_uid is None:
        selected_unit_card = mo.callout(
            mo.md("Click a population point to load unit-level details."),
            kind="info",
        )
    else:
        metadata_fields = [
            ("Unit UID", selected_unit_uid),
            ("Source", selected_point.get("source_name", "")),
            ("Unit ID", selected_point.get("unit_id", "")),
            ("Selected pattern", selected_pattern),
            ("Shank", selected_point.get("shank_id", "")),
            ("Best channel", selected_point.get("best_channel", "")),
            ("x (µm)", selected_point.get("x_um", "")),
            ("y/depth (µm)", selected_point.get("y_um", "")),
        ]
        metadata_text = "  \n".join(
            f"**{label}:** {value}" for label, value in metadata_fields
        )
        selected_unit_card = mo.callout(mo.md(metadata_text), kind="neutral")

    selected_unit_card
    return


@app.cell
def _(
    PATTERN_LABELS,
    PATTERN_ORDER,
    first_existing,
    go,
    np,
    pattern_df,
    selected_pattern,
    selected_unit_uid,
):
    if selected_unit_uid is None:
        pattern_unit = pattern_df.iloc[0:0].copy()
        pattern_response_chart = go.Figure()
        pattern_response_chart.add_annotation(
            text="Select a population point to display the 12-pattern response.",
            x=0.5,
            y=0.5,
            xref="paper",
            yref="paper",
            showarrow=False,
        )
        pattern_response_chart.update_layout(
            height=360,
            xaxis={"visible": False},
            yaxis={"visible": False},
        )
    else:
        pattern_unit = pattern_df[
            pattern_df["unit_uid"].astype(str) == selected_unit_uid
        ].copy()

        pattern_unit["pattern_label"] = pattern_unit["pattern"].map(
            PATTERN_LABELS
        ).fillna(pattern_unit["pattern"].astype(str))
        pattern_to_x = {p: i for i, p in enumerate(PATTERN_ORDER)}
        pattern_unit["pattern_x"] = pattern_unit["pattern"].map(pattern_to_x)

        trial_value_col = first_existing(
            pattern_unit.columns,
            [
                "response_trial",
                "moving_minus_baseline",
                "moving_fr_minus_baseline",
            ],
        )

        if pattern_unit.empty or trial_value_col is None:
            pattern_response_chart = go.Figure()
            pattern_response_chart.add_annotation(
                text="No trial-level 12-pattern response data are available for this unit.",
                x=0.5,
                y=0.5,
                xref="paper",
                yref="paper",
                showarrow=False,
            )
            pattern_response_chart.update_layout(
                height=360,
                xaxis={"visible": False},
                yaxis={"visible": False},
            )
        else:
            import pandas as _pd

            pattern_plot = pattern_unit.copy()
            pattern_plot["response_trial_plot"] = _pd.to_numeric(
                pattern_plot[trial_value_col],
                errors="coerce",
            )
            pattern_plot = pattern_plot[
                pattern_plot["pattern_x"].notna()
                & pattern_plot["response_trial_plot"].notna()
            ].copy()

            # Deterministic horizontal jitter: the same trial always appears in
            # the same position after any reactive rerun.
            _rng = np.random.default_rng(42)
            _sort_cols = [
                c for c in ["pattern_x", "trial_id"]
                if c in pattern_plot.columns
            ]
            pattern_plot = pattern_plot.sort_values(
                _sort_cols,
                kind="stable",
            ).copy()
            pattern_plot["pattern_x_jitter"] = (
                pattern_plot["pattern_x"].astype(float)
                + _rng.normal(0.0, 0.075, size=len(pattern_plot))
            )

            pattern_trial_summary = (
                pattern_plot.groupby(
                    ["pattern", "pattern_label", "pattern_x"],
                    dropna=False,
                )["response_trial_plot"]
                .agg(["mean", "sem", "count"])
                .reset_index()
                .sort_values("pattern_x", kind="stable")
            )

            pattern_response_chart = go.Figure()

            # Raw trial observations.
            custom_columns = [
                pattern_plot["pattern_label"].astype(str),
                pattern_plot["trial_id"].astype(str),
            ]
            pattern_response_chart.add_trace(
                go.Scatter(
                    x=pattern_plot["pattern_x_jitter"],
                    y=pattern_plot["response_trial_plot"],
                    mode="markers",
                    name="Raw trials",
                    marker={
                        "size": 6,
                        "opacity": 0.48,
                    },
                    customdata=np.column_stack(custom_columns),
                    hovertemplate=(
                        "Pattern: %{customdata[0]}<br>"
                        "Trial: %{customdata[1]}<br>"
                        "Moving − baseline FR: %{y:.4g}"
                        "<extra></extra>"
                    ),
                )
            )

            # Mean response line with SEM.
            mean_sizes = [
                12 if str(p) == str(selected_pattern) else 8
                for p in pattern_trial_summary["pattern"]
            ]
            mean_widths = [
                3 if str(p) == str(selected_pattern) else 1
                for p in pattern_trial_summary["pattern"]
            ]
            pattern_response_chart.add_trace(
                go.Scatter(
                    x=pattern_trial_summary["pattern_x"],
                    y=pattern_trial_summary["mean"],
                    mode="lines+markers",
                    name="Mean ± SEM",
                    error_y={
                        "type": "data",
                        "array": pattern_trial_summary["sem"].fillna(0.0),
                        "visible": True,
                        "thickness": 1.3,
                        "width": 4,
                    },
                    marker={
                        "size": mean_sizes,
                        "line": {"width": mean_widths},
                    },
                    customdata=np.column_stack(
                        [
                            pattern_trial_summary["pattern_label"].astype(str),
                            pattern_trial_summary["sem"].fillna(0.0),
                            pattern_trial_summary["count"],
                        ]
                    ),
                    hovertemplate=(
                        "Pattern: %{customdata[0]}<br>"
                        "Mean response: %{y:.4g}<br>"
                        "SEM: %{customdata[1]:.4g}<br>"
                        "n trials: %{customdata[2]}"
                        "<extra></extra>"
                    ),
                )
            )

            pattern_response_chart.add_hline(
                y=0,
                line_dash="dash",
                line_width=1,
            )
            pattern_response_chart.update_layout(
                title=f"{selected_unit_uid}: full 12-pattern response",
                height=430,
                margin={"l": 70, "r": 25, "t": 60, "b": 115},
                xaxis={
                    "title": "Pattern",
                    "tickmode": "array",
                    "tickvals": list(range(len(PATTERN_ORDER))),
                    "ticktext": [
                        PATTERN_LABELS.get(p, p)
                        for p in PATTERN_ORDER
                    ],
                    "tickangle": -35,
                    "range": [-0.45, len(PATTERN_ORDER) - 0.55],
                },
                yaxis={"title": "Moving − baseline FR"},
                legend={
                    "orientation": "h",
                    "yanchor": "bottom",
                    "y": 1.02,
                    "xanchor": "left",
                    "x": 0,
                },
                hovermode="closest",
            )
    return pattern_response_chart, pattern_unit


