@app.cell
def _(
    DIRECTION_ORDER,
    SCREEN_ORDER,
    direction_df,
    go,
    np,
    pd,
    selected_unit_uid,
):
    if selected_unit_uid is None:
        direction_unit = direction_df.iloc[0:0].copy()
    else:
        direction_unit = direction_df[
            direction_df["unit_uid"].astype(str) == selected_unit_uid
        ].copy()

    def _empty_plotly(title, message):
        fig = go.Figure()
        fig.add_annotation(
            text=message, x=0.5, y=0.5, xref="paper", yref="paper",
            showarrow=False, font=dict(size=15),
        )
        fig.update_xaxes(visible=False)
        fig.update_yaxes(visible=False)
        fig.update_layout(title=title, height=330, margin=dict(l=35, r=25, t=55, b=35))
        return fig

    direction_panels = []
    for screen_name in SCREEN_ORDER:
        screen_data = direction_unit[
            direction_unit["screen_role"].astype(str).str.lower() == screen_name
        ].copy()

        if screen_data.empty:
            polar_fig = _empty_plotly(
                f"{screen_name.title()}: baseline vs moving",
                f"No {screen_name} 8-direction data",
            )
            line_fig = _empty_plotly(
                f"{screen_name.title()}: direction response",
                f"No {screen_name} 8-direction data",
            )
        else:
            for col in ["direction", "baseline_fr_trial", "moving_fr_trial", "response_trial"]:
                screen_data[col] = pd.to_numeric(screen_data[col], errors="coerce")

            summary = (
                screen_data.groupby("direction", as_index=False, dropna=False)
                .agg(
                    baseline_fr_mean=("baseline_fr_trial", "mean"),
                    moving_fr_mean=("moving_fr_trial", "mean"),
                    response_mean=("response_trial", "mean"),
                    response_sd=("response_trial", "std"),
                    response_n=("response_trial", "count"),
                )
            )
            summary["response_sem"] = summary["response_sd"] / np.sqrt(
                summary["response_n"].clip(lower=1)
            )
            summary["direction_order"] = summary["direction"].map(
                {float(d): i for i, d in enumerate(DIRECTION_ORDER)}
            )
            summary = summary.sort_values(["direction_order", "direction"], kind="stable")

            # Plotly Scatterpolar accepts angular coordinates in degrees.
            theta = summary["direction"].tolist()
            baseline_r = summary["baseline_fr_mean"].clip(lower=0).tolist()
            moving_r = summary["moving_fr_mean"].clip(lower=0).tolist()
            if theta:
                theta_closed = theta + [theta[0]]
                baseline_closed = baseline_r + [baseline_r[0]]
                moving_closed = moving_r + [moving_r[0]]
            else:
                theta_closed, baseline_closed, moving_closed = [], [], []

            polar_fig = go.Figure()
            polar_fig.add_trace(
                go.Scatterpolar(
                    theta=theta_closed,
                    r=baseline_closed,
                    mode="lines+markers",
                    name="Baseline FR",
                    hovertemplate="Direction %{theta}°<br>Baseline %{r:.3g} Hz<extra></extra>",
                )
            )
            polar_fig.add_trace(
                go.Scatterpolar(
                    theta=theta_closed,
                    r=moving_closed,
                    mode="lines+markers",
                    name="Moving FR",
                    hovertemplate="Direction %{theta}°<br>Moving %{r:.3g} Hz<extra></extra>",
                )
            )
            polar_fig.update_layout(
                title=f"{screen_name.title()}: baseline vs moving",
                height=360,
                margin=dict(l=55, r=45, t=60, b=35),
                polar=dict(
                    angularaxis=dict(
                        direction="clockwise",
                        rotation=90,
                        tickmode="array",
                        tickvals=DIRECTION_ORDER,
                        ticktext=[f"{d}°" for d in DIRECTION_ORDER],
                    ),
                    radialaxis=dict(rangemode="tozero"),
                ),
                legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="left", x=0),
            )

            # Stable per-trial horizontal jitter, independent of app refreshes.
            jitter_key = screen_data[["unit_uid", "screen_role", "direction", "trial_id"]].astype(str)
            hashed = pd.util.hash_pandas_object(jitter_key, index=False).astype("uint64")
            screen_data["direction_jitter"] = screen_data["direction"] + (
                (hashed % 10001).astype(float) / 10000.0 - 0.5
            ) * 10.0

            line_fig = go.Figure()
            line_fig.add_trace(
                go.Scatter(
                    x=screen_data["direction_jitter"],
                    y=screen_data["response_trial"],
                    mode="markers",
                    name="Raw trials",
                    marker=dict(size=7, opacity=0.48),
                    customdata=np.column_stack(
                        [screen_data["trial_id"].astype(str), screen_data["direction"]]
                    ),
                    hovertemplate=(
                        "Trial %{customdata[0]}<br>Direction %{customdata[1]}°"
                        "<br>Moving − baseline %{y:.3g} Hz<extra></extra>"
                    ),
                )
            )
            line_fig.add_trace(
                go.Scatter(
                    x=summary["direction"],
                    y=summary["response_mean"],
                    mode="lines+markers",
                    name="Mean ± SEM",
                    error_y=dict(
                        type="data",
                        array=summary["response_sem"].fillna(0).to_numpy(),
                        visible=True,
                    ),
                    hovertemplate=(
                        "Direction %{x}°<br>Mean %{y:.3g} Hz"
                        "<br>SEM %{error_y.array:.3g}<extra></extra>"
                    ),
                )
            )
            line_fig.add_hline(y=0, line_dash="dash")
            line_fig.update_layout(
                title=f"{screen_name.title()}: direction response",
                height=360,
                margin=dict(l=60, r=35, t=60, b=55),
                xaxis=dict(
                    title="Direction (deg)",
                    tickmode="array",
                    tickvals=DIRECTION_ORDER,
                    range=[-18, 333],
                ),
                yaxis=dict(title="Moving − baseline FR (Hz)"),
                legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="left", x=0),
            )

        direction_panels.append((screen_name, polar_fig, line_fig))
    return direction_panels, direction_unit


@app.cell
def _(direction_panels, mo, selected_unit_uid):
    if selected_unit_uid is None:
        direction_display = mo.callout(
            mo.md("Select a unit to display 8-direction results."), kind="info"
        )
    else:
        rows = []
        for _screen, _polar, _line in direction_panels:
            rows.append(mo.hstack([_polar, _line], widths=[1, 1.35], gap=1))
        direction_display = mo.vstack(rows, gap=1)

    mo.md("## 8-direction summary")
    direction_display
    return


@app.cell
def _(
    available_stat_columns,
    direction_unit,
    pattern_unit,
    selected_pattern,
    stat_table_long,
):
    pattern_stat_columns = available_stat_columns(pattern_unit)
    direction_stat_columns = available_stat_columns(direction_unit)

    # Pattern-level p/q values are repeated on every trial row. Keep one row
    # per pattern before making the long statistics table.
    _pattern_stat_source = pattern_unit.drop_duplicates(
        ["source_name", "unit_id", "unit_uid", "pattern"],
        keep="first",
    )

    pattern_stats_long = stat_table_long(
        _pattern_stat_source,
        ["source_name", "unit_id", "unit_uid", "pattern", "pattern_order"],
        pattern_stat_columns,
    )
    if not pattern_stats_long.empty:
        pattern_stats_long["selected_pattern"] = (
            pattern_stats_long["pattern"].astype(str) == str(selected_pattern)
        )
        pattern_stats_long = pattern_stats_long.sort_values(
            ["pattern_order", "statistic"], kind="stable"
        )

    direction_stats_long = stat_table_long(
        direction_unit,
        [
            "source_name",
            "unit_id",
            "unit_uid",
            "screen_role",
            "speed",
            "direction",
            "screen_order",
            "direction_order",
        ],
        direction_stat_columns,
    )
    if not direction_stats_long.empty:
        direction_stats_long = direction_stats_long.sort_values(
            ["screen_order", "speed", "direction_order", "statistic"],
            kind="stable",
        )
    return direction_stats_long, pattern_stats_long


@app.cell
def _(direction_stats_long, mo, pattern_stats_long, selected_unit_uid):
    if selected_unit_uid is None:
        stats_display = mo.callout(
            mo.md("Select a unit to display p/q values."), kind="info"
        )
    else:
        pattern_table = (
            mo.ui.table(
                pattern_stats_long,
                label="12-pattern p/q values",
                pagination=True,
                page_size=24,
                selection=None,
            )
            if not pattern_stats_long.empty
            else mo.callout(mo.md("No 12-pattern p/q columns found."), kind="warn")
        )
        direction_table = (
            mo.ui.table(
                direction_stats_long,
                label="8-direction p/q values",
                pagination=True,
                page_size=24,
                selection=None,
            )
            if not direction_stats_long.empty
            else mo.callout(mo.md("No 8-direction p/q data found."), kind="warn")
        )
        stats_display = mo.ui.tabs(
            {
                "12-pattern statistics": pattern_table,
                "8-direction statistics": direction_table,
            }
        )

    mo.md("## Statistical results")
    stats_display
    return


@app.cell
def _(direction_df, mo, pattern_df, population_df):
    data_summary = mo.md(
        f"""
        ---
        **Loaded data**

        - Population points: **{len(population_df):,} rows**, **{population_df['unit_uid'].nunique():,} units**
        - 12-pattern responses: **{len(pattern_df):,} rows**
        - 8-direction responses: **{len(direction_df):,} rows**
        """
    )
    data_summary
    return


if __name__ == "__main__":
    app.run()
